import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.vLhlLNVn.js";const k=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),d={name:"guide/getting-started.md"};function n(o,e,l,p,c,h){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>从零把 BirdAdmin 跑起来只需要四条命令。本章在 README 安装步骤的基础上，补齐了环境要求、验证方式与常见排错。</p><h2 id="_1-准备环境" tabindex="-1">1. 准备环境 <a class="header-anchor" href="#_1-准备环境" aria-label="Permalink to &quot;1. 准备环境&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>要求</th><th>说明</th></tr></thead><tbody><tr><td>Node.js</td><td><code>^20.19.0 || &gt;=22.12.0</code></td><td>来自 <code>package.json</code> 的 <code>engines</code> 字段</td></tr><tr><td>pnpm</td><td>建议 ≥ 10.13.1</td><td>README 徽章标注的推荐版本</td></tr><tr><td>Git</td><td>任意较新版本</td><td>用于克隆仓库</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">README 中的 Node 版本描述已过时</p><p>README 的安装章节写着「现在你必须使用 Node 16+ / 18+ 版本」，但当前 <code>package.json</code> 的 <code>engines</code> 已经要求 <code>^20.19.0 || &gt;=22.12.0</code>，且 Vite 7 本身也不再支持旧版 Node。<strong>请以 <code>engines</code> 为准</strong>，使用 Node 20.19+ 或 22.12+。</p><p>可用 <code>node -v</code> 检查当前版本；多版本管理推荐使用 <code>nvm-windows</code>、fnm 或 Volta。</p></div><h2 id="_2-克隆与安装" tabindex="-1">2. 克隆与安装 <a class="header-anchor" href="#_2-克隆与安装" aria-label="Permalink to &quot;2. 克隆与安装&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 克隆项目</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://gitee.com/web_akai/bird-admin.git</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 进入项目</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bird-admin</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 安装 pnpm（已安装可跳过）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 安装依赖</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p><code>pnpm install</code> 会按照根目录的 <code>pnpm-lock.yaml</code> 还原依赖，建议不要删除锁文件，也不要混用 npm / yarn 安装，以免出现依赖版本漂移。</p><h2 id="_3-启动开发服务器" tabindex="-1">3. 启动开发服务器 <a class="header-anchor" href="#_3-启动开发服务器" aria-label="Permalink to &quot;3. 启动开发服务器&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>该命令等价于 <code>vite</code>。根据 <code>.env</code> 中的配置，默认端口为 <strong>9094</strong>；<code>build/vite/server.ts</code> 里设置了 <code>host: true</code>（允许局域网访问）和 <code>strictPort: false</code>（端口被占用时自动尝试下一个可用端口）。</p><p>启动成功后浏览器访问 <code>http://localhost:9094/</code>。项目使用 hash 路由，地址形如 <code>http://localhost:9094/#/login</code>。</p><div class="tip custom-block"><p class="custom-block-title">想改端口？</p><p>修改根目录 <code>.env</code> 中的 <code>VITE_PORT</code> 后重启开发服务器即可。详见<a href="/guide/configuration.html">环境与配置</a>。</p></div><h2 id="_4-打包发布" tabindex="-1">4. 打包发布 <a class="header-anchor" href="#_4-打包发布" aria-label="Permalink to &quot;4. 打包发布&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>该命令实际执行 <code>vue-tsc -b &amp;&amp; vite build</code>：<strong>先做 TypeScript 类型检查，再进行生产构建</strong>。因此类型报错会导致打包中断，这是刻意设计的质量门禁。</p><p>构建产物默认输出到 <code>dist/</code>，可直接部署到 Nginx、对象存储或各类 Pages 静态托管服务。若部署在子路径下，需同步调整 <code>VITE_BASE_PATH</code>。</p><p>本地预览构建结果：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span></span></code></pre></div><h2 id="_5-登录体验" tabindex="-1">5. 登录体验 <a class="header-anchor" href="#_5-登录体验" aria-label="Permalink to &quot;5. 登录体验&quot;">​</a></h2><p>README 提供的演示账户：</p><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>账户</td><td><code>admin</code></td></tr><tr><td>密码</td><td><code>123456</code></td></tr></tbody></table><blockquote><p>演示站数据无法修改，请下载源码安装体验全部功能。</p></blockquote><p>本地开发时，<code>mock/login.ts</code> 配合 <code>vite-plugin-fake-server</code> 提供了登录假数据，即使没有后端也能走通流程。</p><h2 id="常见问题排查" tabindex="-1">常见问题排查 <a class="header-anchor" href="#常见问题排查" aria-label="Permalink to &quot;常见问题排查&quot;">​</a></h2><p><strong><code>pnpm install</code> 报 Node 版本不支持</strong> 先执行 <code>node -v</code>，确认满足 <code>^20.19.0 || &gt;=22.12.0</code>。部分依赖（Vite 7、UnoCSS 66）对 Node 版本有硬性要求。</p><p><strong>端口 9094 被占用</strong><code>strictPort: false</code> 会让 Vite 自动换到下一个可用端口，留意终端实际打印的地址；也可以直接修改 <code>VITE_PORT</code>。</p><p><strong>构建时 TypeScript 报错</strong><code>pnpm run build</code> 会跑 <code>vue-tsc -b</code>。先修复类型错误，或临时用 <code>pnpm run dev</code> 继续开发（开发模式不做全量类型检查）。</p><p><strong>接口请求 404 / 跨域</strong><code>build/vite/server.ts</code> 中的 <code>/api</code> 代理 <code>target</code> 默认为空字符串，需要按你的后端地址填写；同时核对 <code>.env.*</code> 中的 <code>VITE_API_URL</code>。</p><p><strong>页面刷新后空白</strong> 项目使用 <code>createWebHashHistory()</code>，请确认访问地址包含 <code>#/</code>，且静态托管服务已正确返回 <code>index.html</code>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/guide/configuration.html">环境与配置</a> —— 掌握所有环境变量与脚本</li><li><a href="/guide/project-structure.html">目录结构</a> —— 找到该改哪个文件</li><li><a href="/guide/routing.html">路由与权限</a> —— 添加自己的页面与菜单</li><li><a href="/about/faq.html">常见问题</a> —— 更多问答</li></ul>`,32)])])}const g=a(d,[["render",n]]);export{k as __pageData,g as default};
